/// Reply of `daemon.handshake` when the majors match and the params are
/// valid.
public struct HandshakeAccepted: Codable, Sendable, Equatable {
	/// The protocol version the daemon speaks.
	public let `protocol`: ProtocolVersion
	/// A fresh UUID v7 for each daemon run; event cursors belong to it.
	public let serverInstanceId: UUID
	/// The daemon's version and process.
	public let daemon: DaemonIdentity
	/// The daemon's contract digest.
	public let contractDigest: String
	/// True when the versions match but the digests differ: the connection
	/// works, and the daemon logs one warning.
	public let contractDrift: Bool
	/// The limits the daemon enforces.
	public let limits: Limits
	/// The newest event cursor at handshake time; sequence 0 means no event
	/// yet.
	public let head: EventCursor

	public init(protocol: ProtocolVersion, serverInstanceId: UUID, daemon: DaemonIdentity, contractDigest: String, contractDrift: Bool, limits: Limits, head: EventCursor) {
		self.protocol = `protocol`
		self.serverInstanceId = serverInstanceId
		self.daemon = daemon
		self.contractDigest = contractDigest
		self.contractDrift = contractDrift
		self.limits = limits
		self.head = head
	}
}

/// Params of `daemon.handshake`.
