/// One variant per method, tagged by the method name. Methods without
/// params are unit variants, written without `content`.
public enum Call: Codable, Sendable, Equatable {
	/// The first request on every connection.
	case daemonHandshake(HandshakeParams)
	/// Who the daemon is and where it keeps things.
	case daemonGetInfo
	/// The daemon's health and counters.
	case daemonGetHealth
	/// Platform capabilities, methods, and event kinds the daemon knows.
	case daemonGetCapabilities
	/// Stops the daemon, or stops it so launchd starts it again.
	case daemonShutdown(ShutdownParams)
	/// Starts an event subscription.
	case eventsSubscribe(SubscribeParams)
	/// Ends an event subscription.
	case eventsUnsubscribe(UnsubscribeParams)
	/// One operation with its steps and created items.
	case operationGet(GetOperationParams)
	/// One page of operations, newest first.
	case operationList(ListOperationsParams)
	/// Asks an operation to stop.
	case operationCancel(CancelOperationParams)
	/// Queues an operation that needs recovery again.
	case operationResume(ResumeOperationParams)
	/// Cleans up what it can of an operation that needs recovery, then
	/// closes it.
	case operationAbandon(AbandonOperationParams)
	/// The engine's counters and limits.
	case operationGetStats
	/// Every catalog entry with the facts about the catalog.
	case catalogListProviders
	/// One catalog entry with its versions and artifacts.
	case catalogGetProvider(GetProviderParams)
	/// The secret references, from the cached status.
	case secretList(ListSecretsParams)
	/// One secret reference after a fresh probe.
	case secretStatus(SecretStatusParams)
	/// Fills, generates, copies, or replaces the value behind a reference.
	case secretSet(SetSecretParams)
	/// Reads the value behind a reference, recorded in the audit.
	case secretReveal(RevealSecretParams)
	/// Deletes a reference and the value behind it.
	case secretDelete(DeleteSecretParams)
	/// Creates an instance and starts the operation that initializes it.
	case instanceCreate(CreateInstanceParams)
	/// Starts an instance.
	case instanceStart(StartInstanceParams)
	/// Stops an instance.
	case instanceStop(StopInstanceParams)
	/// One instance with its status.
	case instanceGet(GetInstanceParams)
	/// One page of instances, retained ones left out.
	case instanceList(ListInstancesParams)
	/// The space left on the volume that holds the data root.
	case storageGetCapacity
	/// Resolves a selector and starts the operation that installs the
	/// artifact, or answers that it is installed already.
	case runtimeInstall(InstallRuntimeParams)
	/// Resolves a selector to one artifact without installing it.
	case runtimeResolve(InstallRuntimeParams)
	/// One page of runtimes, with the installs that have not ended.
	case runtimeList(ListRuntimesParams)
	/// One runtime in detail.
	case runtimeGet(GetRuntimeParams)
	/// The create form of an installed runtime: the provider, its
	/// endpoints, and its settings fields, typed from the package.
	case instanceGetCreateForm(GetCreateFormParams)
	/// Judges a create draft without any secret value and changes nothing.
	case instancePreflight(PreflightCreateParams)

	enum CodingKeys: String, CodingKey, Codable {
		case daemonHandshake = "daemon.handshake",
			daemonGetInfo = "daemon.get_info",
			daemonGetHealth = "daemon.get_health",
			daemonGetCapabilities = "daemon.get_capabilities",
			daemonShutdown = "daemon.shutdown",
			eventsSubscribe = "events.subscribe",
			eventsUnsubscribe = "events.unsubscribe",
			operationGet = "operation.get",
			operationList = "operation.list",
			operationCancel = "operation.cancel",
			operationResume = "operation.resume",
			operationAbandon = "operation.abandon",
			operationGetStats = "operation.get_stats",
			catalogListProviders = "catalog.list_providers",
			catalogGetProvider = "catalog.get_provider",
			secretList = "secret.list",
			secretStatus = "secret.status",
			secretSet = "secret.set",
			secretReveal = "secret.reveal",
			secretDelete = "secret.delete",
			instanceCreate = "instance.create",
			instanceStart = "instance.start",
			instanceStop = "instance.stop",
			instanceGet = "instance.get",
			instanceList = "instance.list",
			storageGetCapacity = "storage.get_capacity",
			runtimeInstall = "runtime.install",
			runtimeResolve = "runtime.resolve",
			runtimeList = "runtime.list",
			runtimeGet = "runtime.get",
			instanceGetCreateForm = "instance.get_create_form",
