			case .runtimeResolve:
				if let content = try? container.decode(InstallRuntimeParams.self, forKey: .content) {
					self = .runtimeResolve(content)
					return
				}
			case .runtimeList:
				if let content = try? container.decode(ListRuntimesParams.self, forKey: .content) {
