/// The only frame a client sends.
public struct Request: Codable, Sendable, Equatable {
	/// 1 to 64 bytes of `[A-Za-z0-9._:-]`, chosen by the client and unique
	/// on the connection while the request runs. `stackly-ipc` uses a
	/// lowercase UUID v7.
	public let requestId: String
	/// 1 to 128 bytes of printable ASCII without spaces. Spec 0007 decides
	/// what it means.
	public let idempotencyKey: String?
	/// The method and its params.
	public let call: Call

	public init(requestId: String, idempotencyKey: String?, call: Call) {
		self.requestId = requestId
		self.idempotencyKey = idempotencyKey
		self.call = call
	}
}

/// One variant per method, with the same names and tags as [`Call`].
public enum Reply: Codable, Sendable, Equatable {
	/// The handshake was accepted.
	case daemonHandshake(HandshakeAccepted)
	/// Who the daemon is.
	case daemonGetInfo(DaemonInfo)
	/// The daemon's health.
	case daemonGetHealth(DaemonHealth)
	/// What the daemon supports.
	case daemonGetCapabilities(Capabilities)
	/// The daemon accepted the request and now runs the stop order.
	case daemonShutdown(ShutdownAccepted)
	/// The subscription started; its events follow.
	case eventsSubscribe(Subscribed)
	/// The subscription ended.
	case eventsUnsubscribe
	/// The operation with its steps and created items.
	case operationGet(OperationDetail)
	/// One page of operations.
	case operationList(OperationPage)
	/// The operation after the cancel, and what the cancel did.
	case operationCancel(CancelReply)
	/// The operation, queued again.
	case operationResume(OperationSummary)
	/// The closed operation and what was left over.
	case operationAbandon(AbandonReply)
	/// The engine's counters and limits.
	case operationGetStats(OperationStats)
	/// Every catalog entry, in display order.
	case catalogListProviders(ListProvidersReply)
	/// One catalog entry in detail.
	case catalogGetProvider(ProviderDetail)
	/// The secret references and the store.
	case secretList(ListSecretsReply)
	/// The reference after the probe, and the store.
	case secretStatus(SecretStatusReply)
	/// The reference after the write, never the value.
	case secretSet(SetSecretReply)
	/// The value; the one reply that carries one.
	case secretReveal(RevealSecretReply)
	/// The reference that was deleted.
	case secretDelete(DeleteSecretReply)
	/// The operation that creates the instance.
	case instanceCreate(InstanceActionAccepted)
	/// The operation that starts the instance, or that it already runs.
	case instanceStart(InstanceActionAccepted)
	/// The operation that stops the instance, or that it already stopped.
	case instanceStop(InstanceActionAccepted)
	/// The instance.
	case instanceGet(InstanceSummary)
	/// One page of instances.
	case instanceList(InstancePage)
	/// The space left, read now.
	case storageGetCapacity(CapacityReport)
	/// The artifact the selector resolved to, and what happened to it.
	case runtimeInstall(InstallRuntimeReply)
	/// The artifact the selector resolved to.
	case runtimeResolve(ResolvedArtifact)
	/// One page of runtimes.
	case runtimeList(RuntimeListPage)
	/// The runtime.
	case runtimeGet(RuntimeDetail)
	/// The form for a new instance.
	case instanceGetCreateForm(CreateForm)
	/// The preflight rows, the field issues, and the equivalent command.
	case instancePreflight(CreatePreflight)

	enum CodingKeys: String, CodingKey, Codable {
		case daemonHandshake = "daemon.handshake",
			daemonGetInfo = "daemon.get_info",
			daemonGetHealth = "daemon.get_health",
			daemonGetCapabilities = "daemon.get_capabilities",
			daemonShutdown = "daemon.shutdown",
			eventsSubscribe = "events.subscribe",
			eventsUnsubscribe = "events.unsubscribe",
			operationGet = "operation.get",
			operationList = "operation.list",
			operationCancel = "operation.cancel",
			operationResume = "operation.resume",
			operationAbandon = "operation.abandon",
			operationGetStats = "operation.get_stats",
			catalogListProviders = "catalog.list_providers",
			catalogGetProvider = "catalog.get_provider",
			secretList = "secret.list",
			secretStatus = "secret.status",
			secretSet = "secret.set",
			secretReveal = "secret.reveal",
			secretDelete = "secret.delete",
			instanceCreate = "instance.create",
			instanceStart = "instance.start",
			instanceStop = "instance.stop",
			instanceGet = "instance.get",
			instanceList = "instance.list",
			storageGetCapacity = "storage.get_capacity",
			runtimeInstall = "runtime.install",
			runtimeResolve = "runtime.resolve",
			runtimeList = "runtime.list",
			runtimeGet = "runtime.get",
			instanceGetCreateForm = "instance.get_create_form",
			instancePreflight = "instance.preflight"
	}

	private enum ContainerCodingKeys: String, CodingKey {
		case type, content
	}

	public init(from decoder: Decoder) throws {
